# LLMule installer for Windows. https://llmule.xyz
#
#   irm https://llmule.xyz/install.ps1 | iex
#
# Downloads the LLMule binary, checks its sha256 against the one in this script, puts it in
# ~\.llmule\bin\llmule.exe and opens it. No admin; nothing is written outside ~\.llmule.
# Remove it: ~\.llmule\bin\llmule.exe --uninstall, then delete ~\.llmule.
#
# Env: LLMULE_HOME (default ~\.llmule; the app reads it too) - LLMULE_NO_RUN=1 (install only)
#
# Source (MIT): https://github.com/andycufari/llmule
# This file is generated by installer/tools/gen-install.mjs from install.ps1.tmpl: edit the template.
#
# It never calls `exit`: under `irm | iex` that would close the person's PowerShell window.

& {
  $ErrorActionPreference = 'Stop'
  # The progress bar of Invoke-WebRequest makes an 80 MB download take minutes on Windows PowerShell 5.1
  $ProgressPreference = 'SilentlyContinue'

  $Version = '0.2.3-test'
  $Base = 'https://cm64-ss-public.s3.amazonaws.com/67608172a31516c083602958/installer'
  $Want = 'bacd9c144d902e228023642abf4c209c4d3440a12ea5bda08c3ace388793c5e1'

  $es = $false
  try { $es = ((Get-Culture).TwoLetterISOLanguageName -eq 'es') } catch { }
  function Say([string]$en, [string]$sp) { if ($es) { Write-Host $sp } else { Write-Host $en } }
  function Fail([string]$en, [string]$sp) { if ($es) { Write-Host "llmule: $sp" -ForegroundColor Red } else { Write-Host "llmule: $en" -ForegroundColor Red } }

  # 32-bit PowerShell on 64-bit Windows reports x86 here and the real one in PROCESSOR_ARCHITEW6432
  $arch = $env:PROCESSOR_ARCHITECTURE
  if ($env:PROCESSOR_ARCHITEW6432) { $arch = $env:PROCESSOR_ARCHITEW6432 }
  if ($arch -eq 'ARM64') {
    Say 'Windows on ARM: installing the x64 version (Windows runs it emulated).' 'Windows en ARM: instalo la versión x64 (Windows la corre emulada).'
  } elseif ($arch -ne 'AMD64') {
    Fail "LLMule doesn't run on Windows $arch yet. Tell me on Discord: https://discord.gg/uM8fFz56YB" "LLMule todavía no corre en Windows $arch. Contame en Discord: https://discord.gg/uM8fFz56YB"
    return
  }

  $root = if ($env:LLMULE_HOME) { $env:LLMULE_HOME } else { Join-Path $HOME '.llmule' }
  $dir = Join-Path $root 'bin'
  $exe = Join-Path $dir 'llmule.exe'
  $shown = $exe
  if ($exe.StartsWith($HOME)) { $shown = '~' + $exe.Substring($HOME.Length) }
  $file = "llmule-$Version-windows-x64.exe"
  $url = "$Base/$file"

  Say "LLMule $Version for windows-x64" "LLMule $Version para windows-x64"
  New-Item -ItemType Directory -Force -Path $dir | Out-Null
  $tmp = Join-Path $dir ('.llmule-download-' + [guid]::NewGuid().ToString('N') + '.exe')

  # Windows PowerShell 5.1 may still default to TLS 1.0
  try { [Net.ServicePointManager]::SecurityProtocol = [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12 } catch { }

  try {
    Invoke-WebRequest -UseBasicParsing -Uri $url -OutFile $tmp
  } catch {
    Remove-Item -LiteralPath $tmp -Force -ErrorAction SilentlyContinue
    Fail "couldn't download $url ($($_.Exception.Message))" "no pude bajar $url ($($_.Exception.Message))"
    return
  }

  $got = (Get-FileHash -Algorithm SHA256 -LiteralPath $tmp).Hash.ToLowerInvariant()
  if ($got -ne $Want) {
    Remove-Item -LiteralPath $tmp -Force -ErrorAction SilentlyContinue
    Fail "the download doesn't match its sha256 (got $got). Nothing was installed." "lo que bajé no coincide con su sha256 (dio $got). No instalé nada."
    return
  }
  try { Unblock-File -LiteralPath $tmp } catch { }

  try {
    Move-Item -LiteralPath $tmp -Destination $exe -Force
  } catch {
    Remove-Item -LiteralPath $tmp -Force -ErrorAction SilentlyContinue
    Fail "couldn't replace $shown. Is LLMule open? Close it and run this again." "no pude reemplazar $shown. ¿Está LLMule abierto? Cerralo y corré esto de nuevo."
    return
  }

  $ok = $false
  try { & $exe --version | Out-Null; $ok = ($LASTEXITCODE -eq 0) } catch { }
  if (-not $ok) {
    Fail "installed $shown, but it doesn't start on this machine. Tell me on Discord: https://discord.gg/uM8fFz56YB" "instalé $shown, pero no arranca en esta máquina. Contame en Discord: https://discord.gg/uM8fFz56YB"
    return
  }
  Say "sha256 OK. Installed in $shown" "sha256 OK. Instalado en $shown"

  if (-not $env:LLMULE_NO_RUN) {
    Say 'Opening LLMule...' 'Abriendo LLMule...'
    & $exe
  } else {
    Say "Next: run $shown (it links your llmule.xyz account and starts sharing)." "Próximo paso: corré $shown (vincula tu cuenta de llmule.xyz y empieza a compartir)."
  }
}
